import openpyxl
wb = openpyxl.load_workbook('3_39667_answer_inconsistent_color_5758_input.xlsx')
ws = wb['Pay Items']
for row in ws.iter_rows(min_row=1, max_row=ws.max_row, max_col=ws.max_column):
    for c in row:
        f = c.fill
        if f.fill_type is not None:
            try:
                fg = f.fgColor.rgb
            except Exception as e:
                fg = f'ERR:{e}'
            try:
                bg = f.bgColor.rgb
            except Exception as e:
                bg = f'ERR:{e}'
            print(c.coordinate, 'type=', f.fill_type, 'pattern=', f.patternType, 'fg=', fg, 'bg=', bg, 'fg_type=', f.fgColor.type, 'bg_type=', f.bgColor.type, 'fg_theme=', f.fgColor.theme, 'fg_tint=', f.fgColor.tint, 'fg_indexed=', f.fgColor.indexed)
